beforeAll(()=>{if(enabled)db=createDatabaseClient(process.env.DATABASE_URL)});afterAll(async()=>{if(db)await db.$disconnect()});
function repo(){return createPlatformSqlRepository(db as unknown as PlatformSqlDatabase)}
async function fixture(kind:'bucket'|'access'='bucket',account='123456789012',tracked=true,ttlSeconds=60){
 const id='platform_action_'+randomUUID(),selection={operation:kind==='bucket'?'create_bucket':'access',accountId:account,region:'us-east-2',expiresAt:new Date(Date.now()+60000).toISOString(),...(kind==='access'?{objectVersion:'version-1',ttlSeconds,delivery:'original_requester_session'}:{})},profile={accountId:account,region:'us-east-2',profileDigest:d,access:kind==='access'?{artifactProfileDigest:d,clockSkewMs:1000}:null},prepared=await prepareTemplateExecutionPlan(selection,Date.now(),id,actor,profile),{plan,binding}=prepared,r=repo(),authority={assertCurrent:async()=>{},assertEffectCurrent:async()=>{}};
 await r.transaction(async tx=>{await tx.lock(id);const state=createPlatformAction(plan,actor,await tx.now());await tx.insert(id,state);await tx.event({actionId:id,kind:'proposed',state,...(tracked?{templateBinding:binding}:{})})});
 const service=createPlatformActionService(r,authority);if(tracked)await createTemplatePreparationStore(r,authority,{read:async()=>profile,assertQualified:async()=>{}}).review(id,0,plan.digest,reviewer);else await service.review(id,0,plan.digest,reviewer);
 // Storage-only fixture: synthesize the exact already-reviewed parent/child
 // state. This is not native qualification or accepted default execution.
 await r.transaction(async tx=>{await tx.lock(id);const old=readPlatformAction(await tx.read(id)),state=claimPlatformAction(old,actor,await tx.now());await tx.replace(id,old.version,state);await tx.event({actionId:id,kind:'claimed',state});await tx.writeEffect(id,0,null,'claimed');await tx.event({actionId:id,kind:'effect.claimed',state,effectIndex:0})});
 const finish=()=>r.transaction(async tx=>{await tx.lock(id);const old=readPlatformAction(await tx.read(id));await tx.writeEffect(id,0,'claimed','confirmed');const state=finishPlatformAction(old,'confirmed',await tx.now());await tx.replace(id,old.version,state);await tx.event({actionId:id,kind:'effect.observed',state,effectIndex:0,outcome:'confirmed'})});return {id,binding,r,service,finish};
}
async function stored<T>(f:Awaited<ReturnType<typeof fixture>>,fn:(s:ReturnType<typeof createTemplateStorageSql>)=>Promise<T>){return (db as unknown as PlatformSqlDatabase).$transaction(async sql=>{await sql.$queryRawUnsafe('SELECT 1 FROM pg_advisory_xact_lock(hashtextextended($1,0))','axiom-platform-governance:'+f.id);return fn(createTemplateStorageSql(sql,()=>f.id))},{isolationLevel:'ReadCommitted',timeout:10000,maxWait:5000})}
